QR.openPainter = function() {
  var w, h, dims, cb;
  
  dims = $.tag('input', $.id('qr-painter-ctrl'));
  
  w = +dims[0].value;
  h = +dims[1].value;
  
  if (w < 1 || h < 1) {
    return;
  }
  
  cb = $.cls('oe-r-cb', $.id('qr-painter-ctrl'))[0];
  
  Keybinds.enabled = false;
  
  window.Tegaki.open({
    onDone: QR.onPainterDone,
    onCancel: QR.onPainterCancel,
    saveReplay: cb && cb.checked,
    width: w,
    height: h
  });
};

QR.onPainterDone = function() {
  var el, cnt;
  
  Keybinds.enabled = true;
  
  QR.painterData = Tegaki.flatten().toDataURL('image/png');
  
  if (Tegaki.saveReplay) {
    QR.replayBlob = Tegaki.replayRecorder.toBlob();
  }
  
  QR.painterTime = 0;
  
  if (Tegaki.startTimeStamp) {
    if (!Tegaki.hasCustomCanvas || QR.painterSrc) {
      QR.painterTime = Math.round((Date.now() - Tegaki.startTimeStamp) / 1000);
    }
  }
  
  if (el = $.id('qrFile')) {
    el.style.visibility = 'hidden';
  }
  
  cnt = $.id('qr-painter-ctrl');
  
  if (el = $.tag('button', cnt)[0]) {
    el.textContent = 'Edit';
  }
  
  if (el = $.tag('button', cnt)[1]) {
    el.disabled = false;
  }
  
  for (el of $.tag('input', cnt)) {
    el.disabled = true;
  }
};

QR.onPainterCancel = function() {
  var el, cnt;
  
  Keybinds.enabled = true;
  
  QR.painterData = null;
  QR.painterSrc = null;
  QR.replayBlob = null;
  QR.painterTime = 0;
  
  if (el = $.id('qrFile')) {
    el.style.visibility = '';
  }
  
  cnt = $.id('qr-painter-ctrl');
  
  if (el = $.tag('button', cnt)[0]) {
    el.textContent = 'Draw';
  }
  
  if (el = $.tag('button', cnt)[1]) {
    el.disabled = true;
  }
  
  for (el of $.tag('input', cnt)) {
    el.disabled = false;
  }
};

qr_close.text:
QR.close = function() {
  var el, cnt = $.id('quickReply');
  
  QR.comField = null;
  QR.currentTid = null;
  
  QR.painterTime = 0;
  QR.painterData = null;
  QR.painterSrc = null;
  QR.replayBlob = null;
  QR.canvasLoading = false;
  
  clearInterval(QR.pulse);
  
  if (QR.xhr) {
    QR.xhr.abort();
    QR.xhr = null;
  }
  
  cnt.removeEventListener('click', QR.onClick, false);
  
  (el = $.id('qrFile')) && el.removeEventListener('change', QR.startCooldown, false);
  (el = $.id('qrEmail')) && el.removeEventListener('change', QR.startCooldown, false);
  $.tag('textarea', cnt)[0].removeEventListener('keydown', QR.onKeyDown, false);
  
  Draggable.unset($.id('qrHeader'));
  
  if (!QR.noCaptcha) {
    QR.setCTTag();
  }
  
  if (window.t_captcha && TCaptcha.node === QR.captchaWidgetCnt) {
    TCaptcha.destroy();
  }
  
  document.body.removeChild(cnt);
};

